def fill_rect_interior(grid, top, bottom, left, right, color):
    """Fill the interior (not the border) of a rectangular frame"""
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            if grid[r][c] == 6:
                grid[r][c] = color
    return grid

def find_all_regions(grid, color):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    regions = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r, c) not in visited:
                sr, sc = r, c
                queue = [(sr, sc)]
                region = [(sr, sc)]
                visited.add((sr, sc))

                while queue:
                    cr, cc = queue.pop(0)
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if (nr, nc) not in visited and 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color:
                                visited.add((nr, nc))
                                region.append((nr, nc))
                                queue.append((nr, nc))

                return (min(x[0] for x in region), max(x[0] for x in region), 
                        min(x[1] for x in region), max(x[1] for x in region))

    return None

# Check original grid
print("\n=== Checking original grid ===")
for i, row in enumerate(test_input):
    if len(row) != 27:
        print(f"Row {i} has len {len(row)}")

# Now build output grid carefully - DON'T modify in place
