all_regions = {}
for color in [0, 3, 5, 8, 9]:
    bbox = find_all_regions(test_input, color)
    if bbox:
        all_regions[color] = {'bbox': bbox}
    else:
        print(f"No regions found for color {color}")

print("\n=== Regions found ===")
