    print(f"Color {color}: {reg['bbox']}")

# Fill only if the shape has an interior (not just a 1-pixel wide border)
for color in [0, 3, 5, 8, 9]:
    bbox = all_regions[color]['bbox']
    top, bottom, left, right = bbox
    if right - left < 2 or bottom - top < 2:
        print(f"Skipping color {color}, too small interior: {bbox}")
    else:
