print(f"All rows same length: {all(len(row) == 27 for row in grid_output)}")

# Show which rows differ from original
for i, (orig, out) in enumerate(zip(test_input, grid_output)):
    if orig != out:
        print(f"Row {i} changed: orig {orig}, out {out}")

